var ppd = app.getPPDFileInfo(app.PPDFileList[0].name);
for (var i = 0; i < ppd.screenList.length; i++) {
  var s = ppd.screenList[i];
  $.writeln(s.name + ': ' + s.screenInfo.frequency + ' lpi @ ' + s.screenInfo.angle);
}

var fns = app.getPPDFileInfo(app.PPDFileList[0].name).screenSpotFunctionList;
for (var i = 0; i < fns.length; i++) {
  $.writeln(fns[i].name + ' -> ' + fns[i].spotFunction);
}

var doc = app.activeDocument;
var ab = doc.artboards[doc.artboards.getActiveArtboardIndex()];
var r = ab.artboardRect; // [left, top, right, bottom]
ab.artboardRect = [r[0], r[1], r[0] + 1080, r[1] - 1350];
ab.name = 'IG_4x5';

var doc = app.activeDocument;
var st = doc.graphicStyles.getByName('Neon Glow');
for (var i = 0; i < doc.selection.length; i++) {
  st.applyTo(doc.selection[i]);
}

var doc = app.activeDocument;
var b = doc.brushes.getByName('My Art Brush');
var p = doc.pathItems.ellipse(-100, 100, 200, 200);
b.applyTo(p);

var doc = app.activeDocument;
var cp = doc.compoundPathItems.add();
cp.pathItems.ellipse(-100, 100, 200, 200);
cp.pathItems.ellipse(-150, 150, 100, 100, true);
var c = new RGBColor(); c.red = 230; c.green = 30; c.blue = 60;
cp.pathItems[0].fillColor = c;

var opts = new ExportOptionsPNG24();
var d = opts.dimensions;
d.width = 1080; d.height = 1080;
opts.dimensions = d;
app.activeDocument.exportFile(new File('~/Desktop/tile.png'), ExportType.PNG24, opts);

var p = new DocumentPreset();
p.title = 'Poster_A3';
p.width = 842; p.height = 1191; // points
p.colorMode = DocumentColorSpace.CMYK;
p.units = RulerUnits.Millimeters;
var doc = app.documents.addDocument(app.startupPresetsList[0], p);

var items = app.activeDocument.embeddedItems;
for (var i = 0; i < items.length; i++) {
  var e = items[i];
  $.writeln(e.typename + ' ' + (e.file ? e.file.fsName : '(no file)'));
}

var doc = app.activeDocument;
var g = doc.gradients.add();
g.name = 'Sunset'; g.type = GradientType.LINEAR;
var gc = new GradientColor(); gc.gradient = g;
var r = doc.pathItems.rectangle(0, 0, 1080, 1080);
r.fillColor = gc;

var g = app.activeDocument.gradients.getByName('Sunset');
var a = new RGBColor(); a.red = 255; a.green = 94; a.blue = 58;
var b = new RGBColor(); b.red = 255; b.green = 42; b.blue = 104;
g.gradientStops[0].color = a;
g.gradientStops[1].color = b;
g.gradientStops[1].opacity = 60;

var doc = app.activeDocument;
var v = doc.variables.add();
v.kind = VariableKind.GRAPH; v.name = 'salesChart';
doc.graphItems[0].contentVariable = v;

var doc = app.activeDocument;
var g = doc.groupItems.add();
var photo = g.placedItems.add();
photo.file = new File('~/Desktop/photo.jpg');
var mask = g.pathItems.ellipse(-50, 50, 400, 400);
mask.clipping = true;
g.clipped = true;

var doc = app.activeDocument;
var bg = doc.layers.add();
bg.name = 'BG';
bg.zOrder(ZOrderMethod.SENDTOBACK);
bg.pathItems.rectangle(0, 0, 1080, 1080);
bg.locked = true;

var items = app.activeDocument.legacyTextItems;
for (var i = items.length - 1; i >= 0; i--) {
  if (!items[i].converted) items[i].convertToNative();
}

var doc = app.activeDocument;
var ls = doc.listStyles.add('Features');
ls.putLeftIndent(0, 18).putFirstLineIndent(0, -12);
var para = doc.textFrames[0].paragraphs[0];
para.paragraphAttributes.listStyle = ls;

var meshes = app.activeDocument.meshItems;
$.writeln(meshes.length + ' gradient mesh objects');
for (var i = 0; i < meshes.length; i++) meshes[i].locked = true;

var nn = app.activeDocument.nonNativeItems;
for (var i = 0; i < nn.length; i++) {
  $.writeln(nn[i].typename + ' on layer ' + nn[i].layer.name);
}

var doc = app.activeDocument;
for (var i = 0; i < doc.selection.length; i++) {
  var it = doc.selection[i];
  it.resize(50, 50);
  it.position = [0, 0];
  it.opacity = 80;
}

var doc = app.activeDocument;
var p = doc.pathItems.add();
p.setEntirePath([[0, 0], [200, -100], [400, 0]]);
p.filled = false; p.stroked = true; p.strokeWidth = 4;
p.strokeDashes = [12, 6];

var p = app.activeDocument.pathItems.add();
var a = p.pathPoints.add();
a.anchor = [0, 0]; a.leftDirection = [0, 0]; a.rightDirection = [100, 80];
var b = p.pathPoints.add();
b.anchor = [300, 0]; b.leftDirection = [200, 80]; b.rightDirection = [300, 0];
p.stroked = true;

var doc = app.activeDocument;
var p = doc.placedItems.add();
p.file = new File('~/Desktop/product.png');
p.position = [0, 0];
p.embed();

var doc = app.activeDocument;
var t = doc.placedItems[0].trace();
app.redraw();
if (t.isTracing) {
  var paths = t.tracing.expandTracing();
}

var prefs = app.preferences;
prefs.PDFFileOptions.pageToOpen = 2;
prefs.photoshopFileOptions.preserveLayers = true;
var key = 'myKey'; // an internal key from the Illustrator Prefs file
if (prefs.preferenceExists(key)) $.writeln(prefs.getBooleanPreference(key));

var doc = app.activeDocument;
var r = doc.rasterEffectSettings;
r.resolution = 300; r.transparency = true; r.antiAliasing = true;
doc.rasterEffectSettings = r;

var items = app.activeDocument.rasterItems;
for (var i = 0; i < items.length; i++) {
  var r = items[i];
  $.writeln(r.imageColorSpace + ' ' + r.bitsPerChannel + ' bit, embedded=' + r.embedded);
}

var doc = app.activeDocument;
var art = doc.selection[0];
var o = new RasterizeOptions();
o.resolution = 300; o.transparency = true;
o.antiAliasingMethod = AntiAliasingMethod.ARTOPTIMIZED;
var img = doc.rasterize(art, art.visibleBounds, o);

var doc = app.activeDocument;
var sym = doc.symbols.add(doc.selection[0], SymbolRegistrationPoint.SYMBOLCENTERPOINT);
sym.name = 'Star_Icon';
var inst = doc.symbolItems.add(sym);
inst.position = [300, -300];

var doc = app.activeDocument;
var sym = doc.symbols.getByName('Star_Icon');
for (var i = 0; i < 5; i++) {
  var s = doc.symbolItems.add(sym);
  s.position = [i * 120, -100];
}

var t = new TabStopInfo();
t.position = 216; t.alignment = TabStopAlignment.Right; t.leader = '.';
var para = app.activeDocument.textFrames[0].paragraphs[0];
para.paragraphAttributes.tabStops = [t];

var item = app.activeDocument.selection[0];
var t = item.tags.add();
t.name = 'slot'; t.value = 'headline';
try { $.writeln(item.tags.getByName('slot').value); } catch (e) {}

var fonts = app.textFonts;
var n = 'Montserrat-Bold';
var f = fonts.isFontAvailable(n) ? fonts.getByName(n) : fonts[0];
var tf = app.activeDocument.textFrames.add();
tf.contents = 'SALE';
tf.textRange.characterAttributes.textFont = f;
